import{_ as e,o as i,c as a,a2 as d}from"./chunks/framework.lxr64Vqo.js";const u=JSON.parse('{"title":"📺 Android TV & Kodi Guide","description":"","frontmatter":{},"headers":[],"relativePath":"clients/android-tv-kodi.md","filePath":"clients/android-tv-kodi.md","lastUpdated":1795112636000}'),n={name:"clients/android-tv-kodi.md"};function r(t,o,l,s,c,p){return i(),a("div",null,[...o[0]||(o[0]=[d('<h1 id="📺-android-tv-kodi-guide" tabindex="-1">📺 Android TV &amp; Kodi Guide <a class="header-anchor" href="#📺-android-tv-kodi-guide" aria-label="Permalink to &quot;📺 Android TV &amp; Kodi Guide&quot;">​</a></h1><p>NoxMedia can serve media to any Android TV, Google TV, NVIDIA Shield, Fire TV stick, or Kodi setup across your local network.</p><hr><h2 id="📱-standalone-vs-host-mode" tabindex="-1">📱 Standalone vs. Host Mode <a class="header-anchor" href="#📱-standalone-vs-host-mode" aria-label="Permalink to &quot;📱 Standalone vs. Host Mode&quot;">​</a></h2><p>You can run NoxMedia in two different configurations:</p><ol><li><p><strong>Host on Phone / Server, Play on TV (Recommended)</strong>:</p><ul><li>Run NoxMedia on an always-on Android phone, tablet, or mini-PC.</li><li>Stream to your Android TV using <strong>Stremio</strong>, <strong>Kodi</strong>, or <strong>Nova Video Player</strong>.</li><li>Preserves TV storage and keeps background network activity off the TV processor.</li></ul></li><li><p><strong>Run Directly on Android TV</strong>:</p><ul><li>Sideload NoxMedia APK directly onto your Android TV or NVIDIA Shield.</li><li>NoxMedia will run as a local background service on <code>127.0.0.1:8096</code>.</li><li>Any player installed on the TV can connect locally via loopback.</li></ul></li></ol><hr><h2 id="🦎-kodi-setup-via-jellyfin-addon" tabindex="-1">🦎 Kodi Setup (via Jellyfin Addon) <a class="header-anchor" href="#🦎-kodi-setup-via-jellyfin-addon" aria-label="Permalink to &quot;🦎 Kodi Setup (via Jellyfin Addon)&quot;">​</a></h2><p>Kodi provides great codec versatility for vintage or high-bitrate remux content.</p><h3 id="method-1-official-jellyfin-addon-for-kodi" tabindex="-1">Method 1: Official Jellyfin Addon for Kodi <a class="header-anchor" href="#method-1-official-jellyfin-addon-for-kodi" aria-label="Permalink to &quot;Method 1: Official Jellyfin Addon for Kodi&quot;">​</a></h3><ol><li>In Kodi, install the <strong>Jellyfin for Kodi</strong> addon from the official Jellyfin repository.</li><li>When prompted for server address, enter:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.15:8096</span></span></code></pre></div><em>(replace with your NoxMedia host IP)</em></li><li>Choose <strong>Native (Direct Paths)</strong> or <strong>Add-on (HTTP Stream)</strong> mode. Add-on mode is recommended for Telegram streams.</li><li>Enter any username (e.g. <code>NoxMedia</code>) and leave password empty.</li><li>Kodi will sync your libraries and present posters, episode listings, and custom shelves.</li></ol><hr><h2 id="🚀-recommended-android-tv-players" tabindex="-1">🚀 Recommended Android TV Players <a class="header-anchor" href="#🚀-recommended-android-tv-players" aria-label="Permalink to &quot;🚀 Recommended Android TV Players&quot;">​</a></h2><ul><li><strong>Stremio for Android TV</strong>: Sleek modern UI, poster grids, automatic subtitle fetchers, and remote-friendly navigation.</li><li><strong>Nova Video Player</strong>: Open-source, supports SMB/UPnP and Jellyfin, automatic movie scrapers, and hardware-accelerated playback on low-end chipsets.</li><li><strong>Just Player</strong>: Minimalist Android media player based on ExoPlayer with HDR10+ and Dolby Vision support.</li></ul>',14)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
